<?php
require_once __DIR__.'/caixa_service.php';
$tools=query('SELECT * FROM ferramentas WHERE estoque>0 ORDER BY nome')->fetchAll();
$customers=query('SELECT id,nome,tipo FROM clientes WHERE ?=1 OR criado_por=? ORDER BY nome',[admin()?1:0,$_SESSION['user']['id']])->fetchAll();
$rows=query('SELECT * FROM comprovantes WHERE ?=1 OR usuario_id=? ORDER BY id DESC LIMIT 100',[admin()?1:0,$_SESSION['user']['id']])->fetchAll();
$old=query('SELECT v.* FROM vendas v LEFT JOIN comprovante_itens ci ON ci.venda_id=v.id WHERE ci.venda_id IS NULL AND (?=1 OR v.usuario_id=?) ORDER BY v.id DESC LIMIT 100',[admin()?1:0,$_SESSION['user']['id']])->fetchAll();
$draft=$_SESSION['caixa_form']??[];$aberto=caixaAtual();page('Caixa presencial');?>
<?php if(!$aberto):?><p class="notice">Abra seu caixa para registrar vendas. <a href="index.php?p=turnos">Abertura e fechamento</a></p><?php endif;?><section class="card"><h2>Nova venda</h2><p>Selecione os itens pedidos pelo cliente e registre o pagamento realizado no balcão.</p>
<form method="post" class="form-grid" id="order-form"><?php csrf();?><input type="hidden" name="action" value="sale"><input type="hidden" name="chave" value="<?=e($draft['chave']??bin2hex(random_bytes(32)))?>">
<label>Cliente<select name="cliente_id"><option value="0">Consumidor final</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>" <?=($draft['cliente_id']??0)==$c['id']?'selected':''?>><?=e($c['nome'])?> (<?=$c['tipo']?>)</option><?php endforeach;?></select></label>
<p><a href="index.php?p=clientes">Cadastrar cliente ou empresa</a></p>
<div class="order-items no-print"><label>Buscar ferramenta por ID<input id="cash-search-id" type="text" inputmode="numeric" placeholder="Ex.: 5" autocomplete="off"></label><p id="cash-search-status" role="status">Informe o ID para localizar. Os itens já selecionados continuam na venda.</p><button type="button" class="secondary" id="cash-search-clear">Mostrar todas</button></div>
<div class="table-wrap order-items"><table><thead><tr><th>Ferramenta</th><th>Preço</th><th>Estoque</th><th>Quantidade</th></tr></thead><tbody><?php foreach($tools as $t):?><tr data-cash-id="<?=$t['id']?>"><td><b>#<?=$t['id']?></b> · <?=e($t['nome'])?></td><td><?=money($t['preco'])?></td><td><?=$t['estoque']?> · <?=stockBadge((int)$t['estoque'])?></td><td><input type="number" aria-label="Quantidade de <?=e($t['nome'])?>" min="0" max="<?=$t['estoque']?>" step="1" name="quantidades[<?=$t['id']?>]" data-item-cents="<?=centavos($t['preco'])?>" value="<?=e($draft['quantidades'][$t['id']]??0)?>"></td></tr><?php endforeach;if(!$tools)emptyRow(4);?></tbody></table></div>
<label>Forma de pagamento<select name="forma_pagamento" required><option value="">Selecione</option><?php foreach(['Pix','Cartão de crédito','Boleto'] as $f):?><option value="<?=e($f)?>" <?=($draft['forma_pagamento']??'')===$f?'selected':''?>><?=e($f)?></option><?php endforeach;?></select></label>
<label>Referência do pagamento / boleto<input name="referencia_pagamento" maxlength="120" value="<?=e($draft['referencia_pagamento']??'')?>" placeholder="NSU, identificador Pix ou referência do boleto"></label>
<label class="check-label"><input type="checkbox" name="pagamento_conferido" value="1"> Conferi o recebimento do Pix ou a aprovação na maquininha</label>
<p class="order-items">Pix e cartão são conferidos pelo vendedor. Boleto deve ser emitido no banco e fica <b>A receber</b> até o gerente registrar a baixa. Esta tela registra a venda; não debita cartões nem emite boletos bancários.</p>
<p class="notice order-items">Projeto demonstrativo: toda venda é salva e gera uma nota de venda demonstrativa, sem valor fiscal.</p>
<div class="form-footer"><strong>Total estimado: <span id="cart-total">R$ 0,00</span></strong><button <?=$tools&&$aberto?'':'disabled'?>>Concluir venda e gerar comprovante</button></div></form></section>
<section class="card"><h2><?=admin()?'Últimas vendas':'Minhas últimas vendas'?></h2><div class="table-wrap"><table><thead><tr><th>Nº / data</th><th>Cliente</th><th>Total</th><th>Pagamento</th><th>Situação</th><th>Comprovante</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td>#<?=$r['id']?><small><?=e($r['criado_em'])?></small></td><td><?=e($r['cliente_nome'])?></td><td><?=money($r['total'])?></td><td><?=e($r['forma_pagamento'])?><small><?=e($r['pagamento_status'])?></small></td><td><?=e($r['status'])?></td><td><a href="index.php?p=comprovante&id=<?=$r['id']?>">Abrir / reimprimir</a></td></tr><?php endforeach;if(!$rows)emptyRow(6);?></tbody></table></div></section>
<?php if($old):?><section class="card"><h2>Registros anteriores à versão de caixa</h2><div class="table-wrap"><table><thead><tr><th>Venda</th><th>Item</th><th>Total</th><th>Situação</th><th>Comprovante</th></tr></thead><tbody><?php foreach($old as $r):?><tr><td>#<?=$r['id']?></td><td><?=e($r['produto_nome'])?></td><td><?=money($r['total'])?></td><td><?=e($r['status'])?></td><td><a href="index.php?p=comprovante&venda=<?=$r['id']?>">Abrir</a><?php if(admin()&&$r['status']==='Concluída'):?><form method="post" data-confirm="Cancelar este registro antigo e devolver o estoque?"><?php csrf();?><input type="hidden" name="id" value="<?=$r['id']?>"><button name="action" value="cancel_sale" class="danger">Cancelar registro antigo</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;endpage();
